/** Reproducible measured local HTTP/SQLite exercise. No throughput promise, public Tor or native claim. */
class ServerLoadSecurity600Test {
  @TempDir Path home;
  private static final Gson JSON=new Gson();
  record Account(KeyPair root,KeyPair device,KeyPair recovery,KeyPair app,String id,String deviceId,long generation,Capability cap){}
  record Reply(int status,JsonObject body,long nanos){}
  private IdentityStore identity;private IdentityHttpServer identityHttp;private KeyPair identityKey;
  private static KeyPair pair()throws Exception{return KeyPairGenerator.getInstance("Ed25519").generateKeyPair();}
  private static JsonObject obj(Object... values){JsonObject result=new JsonObject();for(int i=0;i<values.length;i+=2){Object v=values[i+1];String k=values[i].toString();if(v instanceof JsonElement j)result.add(k,j);else if(v instanceof Number n)result.addProperty(k,n);else if(v instanceof Boolean b)result.addProperty(k,b);else result.addProperty(k,v.toString());}return result;}
  private Reply rpc(String operation,JsonObject data)throws Exception {
    String nonce=IdentityProtocol.nonce();byte[] bytes=obj("operation",operation,"nonce",nonce,"data",data).toString().getBytes(StandardCharsets.UTF_8);long start=System.nanoTime();HttpURLConnection c=open(identityHttp.port(),"/identity/v1",bytes,"application/json");
    try{int status=c.getResponseCode();byte[] reply=read(c,status,65536);assertTrue(IdentityProtocol.verify(identityKey.getPublic().getEncoded(),IdentityProtocol.response(identity.audience(),nonce,bytes,reply),IdentityProtocol.unb64(c.getHeaderField("AEGIS-Signature"),64)));return new Reply(status,IdentityRemoteAuthority.parseStrict(reply),System.nanoTime()-start);}finally{c.disconnect();Arrays.fill(bytes,(byte)0);}
  }
  private static HttpURLConnection open(int port,String path,byte[] bytes,String type)throws Exception {
    HttpURLConnection c=(HttpURLConnection)new URL("http://127.0.0.1:"+port+path).openConnection(Proxy.NO_PROXY);c.setInstanceFollowRedirects(false);c.setRequestMethod("POST");c.setConnectTimeout(5000);c.setReadTimeout(15000);c.setDoOutput(true);c.setRequestProperty("Content-Type",type);c.setRequestProperty("Connection","close");c.setFixedLengthStreamingMode(bytes.length);try(OutputStream out=c.getOutputStream()){out.write(bytes);}return c;
  }
  private static byte[] read(HttpURLConnection c,int status,int maximum)throws Exception {try(InputStream in=status<400?c.getInputStream():c.getErrorStream()){byte[] reply=in.readNBytes(maximum+1);if(reply.length>maximum)throw new IOException("Размер тестового ответа");return reply;}}
  private Account register(int i,List<Long> registrationLatency,List<Long> capabilityLatency)throws Exception {
    KeyPair root=pair(),device=pair(),recovery=pair(),app=pair();long time=System.currentTimeMillis();String nonce=IdentityProtocol.nonce();byte[] bytes=IdentityProtocol.registration(identity.audience(),root.getPublic().getEncoded(),device.getPublic().getEncoded(),recovery.getPublic().getEncoded(),"load"+i,time,nonce);
    Reply reply=rpc("register",obj("accountKey",IdentityProtocol.b64(root.getPublic().getEncoded()),"deviceKey",IdentityProtocol.b64(device.getPublic().getEncoded()),"recoveryKey",IdentityProtocol.b64(recovery.getPublic().getEncoded()),"nickname","load"+i,"time",time,"nonce",nonce,"accountProof",IdentityProtocol.b64(IdentityProtocol.sign(root.getPrivate(),bytes)),"deviceProof",IdentityProtocol.b64(IdentityProtocol.sign(device.getPrivate(),bytes))));assertEquals(200,reply.status());registrationLatency.add(reply.nanos());JsonObject session=reply.body().getAsJsonObject("data");String account=session.get("accountId").getAsString(),deviceId=session.get("deviceId").getAsString();long generation=session.get("generation").getAsLong();Set<Scope> scopes=EnumSet.of(Scope.MAIL_READ,Scope.MAIL_SEND);time=System.currentTimeMillis();nonce=IdentityProtocol.nonce();bytes=IdentityProtocol.capabilityRequest(identity.audience(),account,deviceId,generation,App.MAIL,app.getPublic().getEncoded(),scopes,600000,time,nonce);JsonArray list=new JsonArray();scopes.stream().map(Enum::name).sorted().forEach(list::add);
    reply=rpc("issueCapability",obj("accountId",account,"deviceId",deviceId,"generation",generation,"appId","MAIL","proofKey",IdentityProtocol.b64(app.getPublic().getEncoded()),"capabilities",list,"ttl",600000,"time",time,"nonce",nonce,"deviceProof",IdentityProtocol.b64(IdentityProtocol.sign(device.getPrivate(),bytes)),"appProof",IdentityProtocol.b64(IdentityProtocol.sign(app.getPrivate(),bytes))));assertEquals(200,reply.status());capabilityLatency.add(reply.nanos());Capability cap=IdentityProtocol.decodeCapability(reply.body().getAsJsonObject("data").get("capability").getAsString());return new Account(root,device,recovery,app,account,deviceId,generation,cap);
  }
  private Reply authorize(Account account)throws Exception {long time=System.currentTimeMillis();String nonce=IdentityProtocol.nonce();byte[] hash=IdentityProtocol.digest("bounded-load-operation".getBytes(StandardCharsets.US_ASCII));return rpc("authorizeDigest",obj("capability",IdentityProtocol.encodeCapability(account.cap()),"action","attachments.status","bodySha256",IdentityProtocol.b64(hash),"time",time,"nonce",nonce,"proof",IdentityProtocol.b64(IdentityProtocol.sign(account.app().getPrivate(),IdentityProtocol.requestDigest(account.cap(),"attachments.status",hash,time,nonce)))));}
  private Reply attachment(int port,KeyPair signing,Account account,AttachmentProtocol.Request request)throws Exception {
    byte[] metadata=request.encode(),body=AttachmentProtocol.frame(metadata,new byte[0]);String nonce=IdentityProtocol.nonce();long time=System.currentTimeMillis(),start=System.nanoTime();HttpURLConnection c=(HttpURLConnection)new URL("http://127.0.0.1:"+port+"/attachments/v1").openConnection(Proxy.NO_PROXY);c.setRequestMethod("POST");c.setDoOutput(true);c.setConnectTimeout(5000);c.setReadTimeout(15000);c.setFixedLengthStreamingMode(body.length);c.setRequestProperty("Content-Type","application/octet-stream");c.setRequestProperty("Connection","close");c.setRequestProperty("AEGIS-Capability",IdentityProtocol.encodeCapability(account.cap()));c.setRequestProperty("AEGIS-Time",Long.toString(time));c.setRequestProperty("AEGIS-Nonce",nonce);c.setRequestProperty("AEGIS-Proof",IdentityProtocol.b64(IdentityProtocol.sign(account.app().getPrivate(),IdentityProtocol.requestDigest(account.cap(),request.command().action(),IdentityProtocol.digest(metadata),time,nonce))));try{try(var out=c.getOutputStream()){out.write(body);}int status=c.getResponseCode();byte[] reply=read(c,status,65536);assertTrue(IdentityProtocol.verify(signing.getPublic().getEncoded(),AttachmentProtocol.responseSigningBytes(metadata,nonce,reply),IdentityProtocol.unb64(c.getHeaderField("AEGIS-Signature"),64)));try(var in=new DataInputStream(new ByteArrayInputStream(reply))){int n=in.readInt();assertTrue(n>=2&&n<=reply.length-4);return new Reply(status,IdentityRemoteAuthority.parseStrict(in.readNBytes(n)),System.nanoTime()-start);}}finally{c.disconnect();}
  }
  private static <T> List<T> concurrent(int n,int parallel,IntFunction<T> task)throws Exception {
    ThreadPoolExecutor workers=new ThreadPoolExecutor(parallel,parallel,0,TimeUnit.SECONDS,new ArrayBlockingQueue<>(n),r->new Thread(r,"aegis-local-load"),new ThreadPoolExecutor.AbortPolicy());List<Future<T>> pending=new ArrayList<>();try{for(int i=0;i<n;i++){final int index=i;pending.add(workers.submit(()->task.apply(index)));}List<T> result=new ArrayList<>();for(var future:pending)result.add(future.get(30,TimeUnit.SECONDS));return result;}finally{workers.shutdownNow();assertTrue(workers.awaitTermination(5,TimeUnit.SECONDS));}
  }
  private static JsonObject stats(List<Long> values){List<Long> sorted=values.stream().sorted().toList();return obj("requests",values.size(),"p50Millis",sorted.get(Math.max(0,(int)Math.ceil(sorted.size()*.5)-1))/1000000.0,"p95Millis",sorted.get(Math.max(0,(int)Math.ceil(sorted.size()*.95)-1))/1000000.0,"maxMillis",sorted.getLast()/1000000.0);}
  private static RuntimeException wrapped(Exception failure){return new CompletionException(failure);}
  @Test @org.junit.jupiter.api.Timeout(120) void measuredOneHundredSessionsConcurrentRevocationQuotasAndSignedBusy()throws Exception {
    long start=System.nanoTime();com.sun.management.OperatingSystemMXBean os=(com.sun.management.OperatingSystemMXBean)ManagementFactory.getOperatingSystemMXBean();long cpu=os.getProcessCpuTime();JsonObject report=obj("scope","Actual local JVM HTTP/SQLite, not public Tor/native or performance target","accounts",100,"parallelism",4,"sharedWorkEnvironment",true,"heapMaxBytes",Runtime.getRuntime().maxMemory(),"java",System.getProperty("java.version"),"os",System.getProperty("os.name"),"architecture",System.getProperty("os.arch"),"availableProcessors",Runtime.getRuntime().availableProcessors());
    identityKey=pair();byte[] audit=new byte[32];new SecureRandom().nextBytes(audit);identity=new IdentityStore(home.resolve("identity.sqlite"),identityKey,audit,Clock.systemUTC());identityHttp=new IdentityHttpServer(new InetSocketAddress("127.0.0.1",0),identity,identityKey);identityHttp.start();
    try(var identityResource=identity;var httpResource=identityHttp){
      List<Account> accounts=new ArrayList<>();List<Long> registrationLatency=new ArrayList<>(),capabilityLatency=new ArrayList<>();for(int i=0;i<100;i++)accounts.add(register(i,registrationLatency,capabilityLatency));report.add("registration",stats(registrationLatency));report.add("capabilityIssue",stats(capabilityLatency));
      List<Reply> active=concurrent(100,4,i->{try{return rpc("isActive",obj("capability",IdentityProtocol.encodeCapability(accounts.get(i).cap())));}catch(Exception e){throw wrapped(e);}});for(var r:active){assertEquals(200,r.status());assertTrue(r.body().getAsJsonObject("data").get("active").getAsBoolean());}report.add("liveActive100Parallel4",stats(active.stream().map(Reply::nanos).toList()));
      List<Reply> authorized=concurrent(40,4,i->{try{return authorize(accounts.get(i));}catch(Exception e){throw wrapped(e);}});for(var r:authorized)assertEquals(200,r.status());report.add("freshPoPAuthorizeParallel4",stats(authorized.stream().map(Reply::nanos).toList()));
      var remote=new IdentityRemoteAuthority(URI.create("http://127.0.0.1:"+identityHttp.port()+"/identity/v1"),identityKey.getPublic().getEncoded());KeyPair attachmentKey=pair();var quotas=AttachmentStore.Quotas.defaults();
      try(var objects=new AttachmentStore(home.resolve("objects"),Clock.systemUTC(),quotas);var attachments=new AttachmentHttpServer(new InetSocketAddress("127.0.0.1",0),objects,remote::authorize,attachmentKey)){
        attachments.start();String id=UUID.randomUUID().toString();assertEquals(200,attachment(attachments.port(),attachmentKey,accounts.getFirst(),AttachmentProtocol.Request.create(id,accounts.getLast().id(),100,"a".repeat(64),60000)).status());
        List<Reply> statuses=concurrent(50,4,i->{try{return attachment(attachments.port(),attachmentKey,accounts.getFirst(),AttachmentProtocol.Request.control(AttachmentProtocol.Command.STATUS,id));}catch(Exception e){throw wrapped(e);}});for(var r:statuses)assertEquals(200,r.status());report.add("attachmentStatusParallel4",stats(statuses.stream().map(Reply::nanos).toList()));
        int accepted=0,denied=0;for(int i=0;i<18;i++){Account actor=accounts.get(1+i/2);var create=AttachmentProtocol.Request.create(UUID.randomUUID().toString(),accounts.getLast().id(),AttachmentStore.MAX_CIPHERTEXT,"b".repeat(64),60000);int status=attachment(attachments.port(),attachmentKey,actor,create).status();if(status==200)accepted++;else{assertEquals(403,status);denied++;}}
        assertTrue(accepted>0&&denied>0);assertEquals(100+(long)accepted*AttachmentStore.MAX_CIPHERTEXT,objects.reservedBytes());assertTrue(objects.reservedBytes()<=quotas.globalBytes());report.add("defaultQuotaReservations",obj("accepted",accepted,"denied",denied,"reservedCiphertextBytes",objects.reservedBytes(),"actualLargeChunkBytesWritten",0,"globalQuotaBytes",quotas.globalBytes()));
      }
      Path diskHome=home.resolve("disk-guard");Files.createDirectory(diskHome);long free=Files.getFileStore(diskHome).getUsableSpace();var diskQuota=new AttachmentStore.Quotas(quotas.globalBytes(),quotas.perSenderBytes(),Math.addExact(free,1L<<30),quotas.perSenderTransfers(),quotas.globalTransfers());
      try(var diskStore=new AttachmentStore(diskHome.resolve("state"),Clock.systemUTC(),diskQuota);var diskServer=new AttachmentHttpServer(new InetSocketAddress("127.0.0.1",0),diskStore,remote::authorize,attachmentKey)){
        diskServer.start();assertEquals(403,attachment(diskServer.port(),attachmentKey,accounts.getFirst(),AttachmentProtocol.Request.create(UUID.randomUUID().toString(),accounts.getLast().id(),100,"c".repeat(64),60000)).status());assertEquals(0,diskStore.reservedBytes());assertEquals(0,diskStore.transferCount());report.add("diskHighWaterGuard",obj("freeBytesObserved",free,"configuredFreeReserveBytes",diskQuota.freeReserveBytes(),"deniedWithoutPartialObject",true,"scope","Real FileStore free-space refusal; physical ENOSPC not induced"));
      }
      Account owner=accounts.getFirst();var challenge=identity.ownerChallenge(owner.id());identity.bootstrapOwner(owner.id(),challenge.challenge(),IdentityProtocol.sign(owner.root().getPrivate(),IdentityProtocol.ownerBootstrap(identity.audience(),owner.id(),challenge.challenge(),challenge.expiresAt())));var step=identity.stepUpChallenge(owner.id(),owner.deviceId(),owner.generation());byte[] reauth=IdentityProtocol.stepUp(identity.audience(),step.accountId(),step.deviceId(),step.challenge(),step.expiresAt());identity.stepUp(step.accountId(),step.deviceId(),owner.generation(),step.challenge(),IdentityProtocol.sign(owner.root().getPrivate(),reauth),IdentityProtocol.sign(owner.device().getPrivate(),reauth));KeyPair adminApp=pair();long time=System.currentTimeMillis();String nonce=IdentityProtocol.nonce();Set<Scope> scopes=EnumSet.of(Scope.ACCOUNT_READ,Scope.ADMIN);byte[] request=IdentityProtocol.capabilityRequest(identity.audience(),owner.id(),owner.deviceId(),owner.generation(),App.AEGIS,adminApp.getPublic().getEncoded(),scopes,600000,time,nonce);Capability admin=identity.issueCapability(owner.id(),owner.deviceId(),owner.generation(),App.AEGIS,adminApp.getPublic().getEncoded(),scopes,600000,time,nonce,IdentityProtocol.sign(owner.device().getPrivate(),request),IdentityProtocol.sign(adminApp.getPrivate(),request));
      KeyPair managementKey=pair();java.util.concurrent.atomic.AtomicInteger commands=new java.util.concurrent.atomic.AtomicInteger();byte[] managementAudit=new byte[32];new SecureRandom().nextBytes(managementAudit);
      try(var management=new ManagementService(home.resolve("management.sqlite"),managementAudit,remote::authorize,args->{commands.incrementAndGet();return new ManagementService.Result(0,"ActiveState=active\n");},Clock.systemUTC());var endpoint=new ManagementHttpServer600(new InetSocketAddress("127.0.0.1",0),managementKey,bytes->{var envelope=ManagementMain.decode(bytes);var value=management.execute(envelope.request(),envelope.proofs());return obj("exitCode",value.exitCode(),"output",value.safeOutput());})){
        endpoint.start();List<Long> latency=new ArrayList<>();int limited=0;for(int i=0;i<31;i++){var command=new ManagementPolicy.Request(UUID.randomUUID().toString(),ManagementPolicy.Action.STATUS,ManagementPolicy.Service.MAIL_RELAY,"");time=System.currentTimeMillis();nonce=IdentityProtocol.nonce();JsonArray proofs=new JsonArray();proofs.add(obj("capability",IdentityProtocol.encodeCapability(admin),"time",time,"nonce",nonce,"proof",IdentityProtocol.b64(IdentityProtocol.sign(adminApp.getPrivate(),IdentityProtocol.requestDigest(admin,command.action().permission(),IdentityProtocol.digest(command.encode()),time,nonce)))));byte[] body=obj("metadata",IdentityProtocol.b64(command.encode()),"proofs",proofs).toString().getBytes(StandardCharsets.UTF_8);long began=System.nanoTime();HttpURLConnection c=open(endpoint.port(),"/management/v1",body,"application/json");try{int code=c.getResponseCode();byte[] bytes=read(c,code,16384);assertTrue(IdentityProtocol.verify(managementKey.getPublic().getEncoded(),IdentityProtocol.response(IdentityProtocol.id(managementKey.getPublic().getEncoded()),nonce,body,bytes),IdentityProtocol.unb64(c.getHeaderField("AEGIS-Signature"),64)));if(code==429)limited++;else assertEquals(200,code);latency.add(System.nanoTime()-began);}finally{c.disconnect();}}
        assertEquals(30,commands.get());assertEquals(1,limited);assertTrue(management.verifyAudit());report.add("managementStatusAndSignedBusy",stats(latency));report.add("managementLimit",obj("executedRecordedCommands",commands.get(),"signedHttp429",limited,"nativeSystemctl","NOT_RUN"));
      }
      List<Reply> logins=concurrent(100,4,i->{try{Account a=accounts.get(i);long now=System.currentTimeMillis();String n=IdentityProtocol.nonce();return rpc("login",obj("accountId",a.id(),"deviceId",a.deviceId(),"time",now,"nonce",n,"proof",IdentityProtocol.b64(IdentityProtocol.sign(a.device().getPrivate(),IdentityProtocol.login(identity.audience(),a.id(),a.deviceId(),now,n)))));}catch(Exception e){throw wrapped(e);}});for(int i=0;i<logins.size();i++){assertEquals(200,logins.get(i).status());assertTrue(logins.get(i).body().getAsJsonObject("data").get("generation").getAsLong()>accounts.get(i).generation());}report.add("generationRotate100Parallel4",stats(logins.stream().map(Reply::nanos).toList()));
      List<Reply> revoked=concurrent(100,16,i->{try{return rpc("isActive",obj("capability",IdentityProtocol.encodeCapability(accounts.get(i).cap())));}catch(Exception e){throw wrapped(e);}});for(var reply:revoked){assertEquals(200,reply.status());assertFalse(reply.body().getAsJsonObject("data").get("active").getAsBoolean());}report.add("revoked100Parallel16",stats(revoked.stream().map(Reply::nanos).toList()));
      int denied=0;for(int i=0;i<40;i++){assertEquals(403,authorize(accounts.get(i)).status());denied++;}report.addProperty("oldGenerationPoPRefusals",denied);
      int rateLimited=0;for(int i=0;i<700;i++){Reply reply=rpc("nonexistentBoundedControlOperation",new JsonObject());assertTrue(reply.status()==400||reply.status()==429);if(reply.status()==429)rateLimited++;}assertTrue(rateLimited>0);Reply recheck=rpc("isActive",obj("capability",IdentityProtocol.encodeCapability(accounts.getLast().cap())));assertEquals(200,recheck.status());assertFalse(recheck.body().getAsJsonObject("data").get("active").getAsBoolean());report.add("identityControlBudget",obj("boundedInvalidRequests",700,"signedHttp429",rateLimited,"liveRecheckStillAvailable",true));
    }
    report.addProperty("durationMillis",(System.nanoTime()-start)/1000000);report.addProperty("processCpuMillis",(os.getProcessCpuTime()-cpu)/1000000);report.addProperty("heapUsedAtEndBytes",ManagementFactory.getMemoryMXBean().getHeapMemoryUsage().getUsed());report.addProperty("productionReady",false);report.addProperty("physicalDiskExhaustion","NOT_RUN");report.addProperty("nativeSystemdTorAndTwoDevices","NOT_RUN");
    String destination=System.getProperty("aegis.load.report");if(destination!=null)Files.writeString(Path.of(destination),JSON.toJson(report)+"\n",StandardOpenOption.CREATE_NEW);System.out.println("AEGIS_LOCAL_LOAD_REPORT "+JSON.toJson(report));
  }
}
